    slugEn: "alicante-airport-to-sh-villa-gadea",
    slugEs: "traslado-aeropuerto-alicante-a-sh-villa-gadea",
    originNameEn: "Alicante Airport",
    originNameEs: "Aeropuerto de Alicante",
