    kind: "attraction",
    direction: "to-airport",
    originCitySlug: "alicante",
    slugEn: "benidorm-to-alicante-airport",
    slugEs: "benidorm-al-aeropuerto-de-alicante",
    originNameEn: "Benidorm",
    originNameEs: "Benidorm",
    destinationNameEn: "Alicante Airport",
    destinationNameEs: "Aeropuerto de Alicante",
    driveTime: "45 min",
